#!/bin/bash
# Récupère, SANS root, les dépendances Perl de l'agent GLPI (paquets Ubuntu extraits dans ~/supervision-test/perl5).
set -u
D="$HOME/supervision-test"; P="$D/perl5"; mkdir -p "$D/dl-perl" "$P"; cd "$D/dl-perl" || exit 1
PAQUETS="libnamespace-clean-perl libpackage-stash-perl libpackage-stash-xs-perl libb-hooks-endofscope-perl libvariable-magic-perl libclone-perl libdatetime-format-strptime-perl libdatetime-format-builder-perl libparams-validate-perl libtask-weaken-perl libclass-load-perl libclass-load-xs-perl libdata-dumper-concise-perl libscope-guard-perl libdevel-globaldestruction-perl libmoo-perl libclass-method-modifiers-perl librole-tiny-perl libsub-quote-perl libossp-uuid16 libossp-uuid-perl libuniversal-require-perl libnet-ip-perl libparallel-forkmanager-perl libfile-which-perl libxml-libxml-perl libxml-namespacesupport-perl libxml-sax-perl libxml-sax-base-perl libyaml-perl libyaml-tiny-perl libtext-template-perl libcpanel-json-xs-perl libjson-maybexs-perl libtype-tiny-perl libproc-daemon-perl libhttp-daemon-perl libhttp-message-perl libhttp-date-perl libio-html-perl liblwp-mediatypes-perl libencode-locale-perl libtry-tiny-perl libuuid-perl libossp-uuid-perl libdatetime-perl libdatetime-locale-perl libdatetime-timezone-perl libparse-edid-perl libclass-singleton-perl libdatetime-timezone-perl libparams-validationcompiler-perl libspecio-perl libdist-checkconflicts-perl libmodule-runtime-perl libsub-exporter-perl libexception-class-perl libdevel-stacktrace-perl libeval-closure-perl libmro-compat-perl libnamespace-autoclean-perl libb-hooks-endofscope-perl libmodule-implementation-perl libparams-util-perl libclass-data-inheritable-perl libsub-identify-perl libsub-install-perl libdata-optlist-perl libsub-exporter-progressive-perl liblist-moreutils-perl liblist-moreutils-xs-perl libexporter-tiny-perl libtypes-serialiser-perl libcommon-sense-perl libjson-xs-perl libnet-http-perl libnet-ssleay-perl libio-socket-ssl-perl libwww-perl libwww-robotrules-perl libhttp-cookies-perl libhttp-negotiate-perl libfile-listing-perl libhtml-parser-perl libhtml-tagset-perl liburi-perl libnet-ip-perl"
for p in $PAQUETS; do apt-get download "$p" >/dev/null 2>&1 || echo "  (indisponible : $p)"; done
for f in *.deb; do dpkg-deb -x "$f" "$P"; done
echo "$(ls *.deb | wc -l) paquets extraits dans $P"
